export class ArtifactSchemaValidator {

  /**
   * Strictly validates the parsed JSON artifact from a runtime subprocess.
   * Throws an error if the schema is malformed.
   */
  public static validate(data: any): ValidatedRuntimeResponse {
    if (!data || typeof data !== 'object') {
      throw new Error("Artifact is not a valid JSON object");
    }

    if (!['accept', 'reject', 'error'].includes(data.status)) {
      throw new Error(`Invalid status field: ${data.status}`);
    }

    if (typeof data.trace_digest !== 'string') {
      throw new Error("Missing or invalid trace_digest string");
    }

    if (!Array.isArray(data.snapshots)) {
      throw new Error("Missing or invalid snapshots array");
    }

    for (let i = 0; i < data.snapshots.length; i++) {
      const snap = data.snapshots[i];
      if (typeof snap.sequence_index !== 'number') {
        throw new Error(`Snapshot ${i} missing sequence_index`);
      }
      if (typeof snap.hash !== 'string' || snap.hash.length === 0) {
        throw new Error(`Snapshot ${i} missing hash`);
      }
      if (typeof snap.transition_reason !== 'string') {
        throw new Error(`Snapshot ${i} missing transition_reason`);
      }
      // Temporal Ordering Verification: Monotonicity Enforcement
      if (i > 0 && snap.sequence_index <= data.snapshots[i - 1].sequence_index) {
        throw new Error(`Temporal ordering violation: Snapshot ${i} (index ${snap.sequence_index}) is not strictly greater than Snapshot ${i - 1} (index ${data.snapshots[i - 1].sequence_index})`);
      }
    }

    if (data.metrics) {
      if (typeof data.metrics.total_snapshots !== 'number') {
        throw new Error("metrics.total_snapshots missing or invalid");
      }
      if (!Array.isArray(data.metrics.snapshots_per_chunk)) {
        throw new Error("metrics.snapshots_per_chunk missing or invalid");
      }
      if (typeof data.metrics.snapshots_per_byte !== 'number') {
        throw new Error("metrics.snapshots_per_byte missing or invalid");
      }
      if (typeof data.metrics.transition_density !== 'object' || data.metrics.transition_density === null) {
        throw new Error("metrics.transition_density missing or invalid");
      }
      if (data.metrics.telemetry_cost_per_snapshot !== undefined && typeof data.metrics.telemetry_cost_per_snapshot !== 'number') {
        throw new Error("metrics.telemetry_cost_per_snapshot invalid");
      }
      if (data.metrics.topology_cost_per_window !== undefined && typeof data.metrics.topology_cost_per_window !== 'number') {
        throw new Error("metrics.topology_cost_per_window invalid");
      }
      if (data.metrics.memory_growth_per_transition !== undefined && typeof data.metrics.memory_growth_per_transition !== 'number') {
        throw new Error("metrics.memory_growth_per_transition invalid");
      }
      if (data.metrics.serialization_cost_per_frame !== undefined && typeof data.metrics.serialization_cost_per_frame !== 'number') {
        throw new Error("metrics.serialization_cost_per_frame invalid");
      }
      if (data.metrics.stdout_drain_latency !== undefined && typeof data.metrics.stdout_drain_latency !== 'number') {
        throw new Error("metrics.stdout_drain_latency invalid");
      }
    }

    if (data.topology_fingerprint !== undefined && typeof data.topology_fingerprint !== 'string') {
      throw new Error("Invalid topology_fingerprint format");
    }

    if (data.topology_windows !== undefined && (typeof data.topology_windows !== 'object' || data.topology_windows === null)) {
      throw new Error("Invalid topology_windows format");
    }

    if (data.provenance_lineage !== undefined && typeof data.provenance_lineage !== 'object') {
      throw new Error("Invalid provenance_lineage format");
    }

    if (data.cross_runtime_mode !== undefined && !['mirrored', 'differential'].includes(data.cross_runtime_mode)) {
      throw new Error(`Invalid cross_runtime_mode: ${data.cross_runtime_mode}`);
    }

    if (data.infrastructure_failure_metadata !== undefined && typeof data.infrastructure_failure_metadata !== 'object') {
      throw new Error("Invalid infrastructure_failure_metadata format");
    }

    // Pass-through cast now that we have proven its structure
    return data as ValidatedRuntimeResponse;
  }
}

import type { 
  ReplayTelemetryProfile, 
  RuntimeArtifacts, 
  DivergenceClassification, 
  DivergenceWindow,
  ReplayArtifactCollector
} from './ReplayArtifactCollector.js';
import { SemanticProjector } from './SemanticProjector.js';
import { SemanticObjectProjector } from './SemanticObjectProjector.js';
import { RoundtripSemanticStabilizer } from './RoundtripSemanticStabilizer.js';

export class DivergenceComparator {

  /**
   * Compares the artifacts from two runtimes and calculates the divergence classification and windows.
   */
  public static compare(
    primary: RuntimeArtifacts,
    secondary: RuntimeArtifacts,
    payload?: string,
    ecosystemProfile?: 'rfc8259_strict' | 'canonical_order_strict' | 'ecma262' | 'legacy_first_win' | 'duplicate_error'
  ): {
    classification: DivergenceClassification;
    first_divergence_index: number | null;
    divergence_windows: DivergenceWindow[];
  } {
    const windows: DivergenceWindow[] = [];
    let firstDivergence: number | null = null;
    let currentWindow: DivergenceWindow | null = null;

    // Check for infrastructure failure
    if (primary.infrastructure_failure || secondary.infrastructure_failure) {
      const failure = primary.infrastructure_failure || secondary.infrastructure_failure;
      return {
        classification: failure as DivergenceClassification,
        first_divergence_index: null,
        divergence_windows: []
      };
    }

    const maxLen = Math.max(primary.snapshots.length, secondary.snapshots.length);

    for (let i = 0; i < maxLen; i++) {
      const pSnap = primary.snapshots[i];
      const sSnap = secondary.snapshots[i];

      const isDiverged = !pSnap || !sSnap || pSnap.hash !== sSnap.hash;

      if (isDiverged) {
        if (firstDivergence === null) {
          firstDivergence = i;
        }
        if (!currentWindow) {
          currentWindow = { start_snapshot: i, end_snapshot: null };
          windows.push(currentWindow);
        }
      } else {
        // Reconverged
        if (currentWindow) {
          currentWindow.end_snapshot = i;
          currentWindow = null;
        }
      }
    }

    // Determine classification
    let classification: DivergenceClassification = 'none';

    if (primary.final_result !== secondary.final_result) {
      classification = 'reject_trigger_divergence';
    } else if (firstDivergence !== null) {
      const lastWindow = windows[windows.length - 1];
      if (lastWindow && lastWindow.end_snapshot === null) {
        if (primary.snapshots.length !== secondary.snapshots.length) {
          classification = 'cadence_divergence';
        } else if (primary.trace_digest !== secondary.trace_digest) {
          classification = 'persistent_divergence';
        } else {
          classification = 'semantic_divergence';
        }
      } else {
        classification = 'recovering_divergence';
      }
    } else if (primary.trace_digest !== secondary.trace_digest) {
      classification = 'transition_divergence';
    } else {
      if (primary.topology_fingerprint && secondary.topology_fingerprint && primary.topology_fingerprint !== secondary.topology_fingerprint) {
        classification = 'TOPOLOGY_ASYMMETRY';
        if (primary.topology_windows && secondary.topology_windows) {
          const primKeys = Object.keys(primary.topology_windows).sort((a, b) => {
            const aStart = parseInt(a.split('_')[1], 10);
            const bStart = parseInt(b.split('_')[1], 10);
            return aStart - bStart;
          });
          for (const key of primKeys) {
            if (primary.topology_windows[key] !== secondary.topology_windows[key]) {
              const startIdx = parseInt(key.split('_')[1], 10);
              firstDivergence = startIdx;
              windows.push({ start_snapshot: startIdx, end_snapshot: null });
              break;
            }
          }
        }
      } else if (primary.metrics && secondary.metrics) {
        const primChunks = primary.metrics.snapshots_per_chunk.join(',');
        const secChunks = secondary.metrics.snapshots_per_chunk.join(',');
        if (primChunks !== secChunks) {
          classification = 'CADENCE_ASYMMETRY';
        } else {
          const primKeys = Object.keys(primary.metrics.transition_density).sort();
          const secKeys = Object.keys(secondary.metrics.transition_density).sort();
          let densityMatch = primKeys.length === secKeys.length;
          if (densityMatch) {
            for (const key of primKeys) {
              if (primary.metrics.transition_density[key] !== secondary.metrics.transition_density[key]) {
                densityMatch = false;
                break;
              }
            }
          }
          if (!densityMatch) {
            classification = 'TRANSITION_DENSITY_ASYMMETRY' as any;
          }
        }
      }
    }

    if (payload && classification !== 'none' && classification !== 'reject_trigger_divergence') {
      try {
        const proj = SemanticProjector.compare(primary.snapshots, secondary.snapshots, payload);
        
        let astEqual = false;
        let roundtripEqual = false;
        
        try {
          const tsTokens = SemanticObjectProjector.extractTSTokens(primary.snapshots);
          const rustTokens = SemanticObjectProjector.extractRustTokens(secondary.snapshots, payload);
          if (tsTokens.length > 0 && rustTokens.length > 0) {
            const tsAST = SemanticObjectProjector.buildAST(tsTokens, ecosystemProfile);
            const rustAST = SemanticObjectProjector.buildAST(rustTokens, ecosystemProfile);
            const astRes = SemanticObjectProjector.compareASTs(tsAST, rustAST, '', ecosystemProfile);
            astEqual = astRes.isEqual;

            // Perform Roundtrip Semantic Stabilization checks
            const tsReconstructed = tsTokens.map(t => t.value).join('');
            const rustReconstructed = rustTokens.map(t => t.value).join('');
            const tsStable = RoundtripSemanticStabilizer.stabilizeRoundtrip(tsReconstructed);
            const rustStable = RoundtripSemanticStabilizer.stabilizeRoundtrip(rustReconstructed);
            roundtripEqual = (tsStable === rustStable && tsStable !== '');
          } else {
            astEqual = proj.isEqual;
          }
        } catch (e) {
          astEqual = false;
        }

        if ((proj.isEqual && astEqual) || roundtripEqual) {
          classification = 'semantic_aligned_cadence_divergence' as any;
        } else {
          classification = 'semantic_divergence';
        }
      } catch (err) {
        classification = 'semantic_divergence';
      }
    }

    return {
      classification,
      first_divergence_index: firstDivergence,
      divergence_windows: windows
    };
  }

  /**
   * Invokes Replay Shrinking procedures if a divergence is detected.
   */
  public static attemptReplayShrinking(profile: ReplayTelemetryProfile): void {
    if (profile.classification === 'none' || profile.classification === 'recovering_divergence') {
      return;
    }
  }
}

import type { ReplayExecutionContract, RuntimeIdentifier } from './ReplayExecutionContract.js';
import type { ReplayFailureClass } from './ReplayFailureTaxonomy.js';
import type { SnapshotMetrics, ReplayAbandonmentLineage } from './ArtifactSchemaValidator.js';

export interface SnapshotTelemetry {
  sequence_index: number;
  hash: string;
  transition_reason: string;
  metadata?: any;
}

export interface RuntimeArtifacts {
  runtime: RuntimeIdentifier;
  final_result: 'accept' | 'reject' | 'error';
  error_message?: string;
  infrastructure_failure?: ReplayFailureClass;
  trace_digest: string;
  snapshots: SnapshotTelemetry[];
  metrics?: SnapshotMetrics;
  topology_fingerprint?: string;
  topology_windows?: Record<string, string>;
  provenance_lineage?: any;
  cross_runtime_mode?: 'mirrored' | 'differential';
  infrastructure_failure_metadata?: ReplayAbandonmentLineage;
}

export type DivergenceClassification = 
  | 'semantic_divergence'
  | 'cadence_divergence'
  | 'semantic_aligned_cadence_divergence'
  | 'transition_divergence'
  | 'recovering_divergence'
  | 'persistent_divergence'
  | 'reject_trigger_divergence'
  | 'CADENCE_ASYMMETRY'
  | 'TOPOLOGY_ASYMMETRY'
  | 'none'
  | ReplayFailureClass;

export interface DivergenceWindow {
  start_snapshot: number;
  end_snapshot: number | null; // null if it never reconverges (persistent)
}

export interface ReplayTelemetryProfile {
  replay_id: string;
  contract: ReplayExecutionContract;
  chunk_layout_sizes: number[];
  primary_artifacts: RuntimeArtifacts;
  secondary_artifacts: RuntimeArtifacts;
  classification: DivergenceClassification;
  first_divergence_index: number | null;
  divergence_windows: DivergenceWindow[];
}

export class ReplayArtifactCollector {
  private primary: RuntimeArtifacts;
  private secondary: RuntimeArtifacts;
  private chunkSizes: number[] = [];

  constructor(
    private contract: ReplayExecutionContract,
    private replayId: string,
    primaryRuntime: RuntimeIdentifier,
    secondaryRuntime: RuntimeIdentifier
  ) {
    this.primary = this.createEmptyArtifact(primaryRuntime);
    this.secondary = this.createEmptyArtifact(secondaryRuntime);
  }

  private createEmptyArtifact(runtime: RuntimeIdentifier): RuntimeArtifacts {
    return {
      runtime,
      final_result: 'error',
      trace_digest: '',
      snapshots: []
    };
  }

  public recordChunk(size: number) {
    this.chunkSizes.push(size);
  }

  public recordSnapshot(runtime: RuntimeIdentifier, snapshot: SnapshotTelemetry) {
    if (runtime === this.primary.runtime) {
      this.primary.snapshots.push(snapshot);
    } else {
      this.secondary.snapshots.push(snapshot);
    }
  }

  public finalizeRuntime(
    runtime: RuntimeIdentifier,
    finalResult: 'accept' | 'reject' | 'error',
    traceDigest: string,
    errorMessage?: string,
    infrastructureFailure?: ReplayFailureClass,
    metrics?: SnapshotMetrics,
    topologyFingerprint?: string,
    provenanceLineage?: any,
    crossRuntimeMode?: 'mirrored' | 'differential',
    topologyWindows?: Record<string, string>,
    infrastructureFailureMetadata?: ReplayAbandonmentLineage
  ) {
    const art = runtime === this.primary.runtime ? this.primary : this.secondary;
    art.final_result = finalResult;
    art.trace_digest = traceDigest;
    art.error_message = errorMessage;
    if (infrastructureFailure) {
      art.infrastructure_failure = infrastructureFailure;
    }
    if (metrics) {
      art.metrics = metrics;
    }
    if (topologyFingerprint) {
      art.topology_fingerprint = topologyFingerprint;
    }
    if (provenanceLineage) {
      art.provenance_lineage = provenanceLineage;
    }
    if (crossRuntimeMode) {
      art.cross_runtime_mode = crossRuntimeMode;
    }
    if (topologyWindows) {
      art.topology_windows = topologyWindows;
    }
    if (infrastructureFailureMetadata) {
      art.infrastructure_failure_metadata = infrastructureFailureMetadata;
    }
  }

  public generateProfile(
    classification: DivergenceClassification,
    first_divergence_index: number | null,
    divergence_windows: DivergenceWindow[]
  ): ReplayTelemetryProfile {
    return {
      replay_id: this.replayId,
      contract: this.contract,
      chunk_layout_sizes: this.chunkSizes,
      primary_artifacts: this.primary,
      secondary_artifacts: this.secondary,
      classification,
      first_divergence_index,
      divergence_windows
    };
  }
}

import * as crypto from 'node:crypto';

export type RuntimeIdentifier = 'rust' | 'typescript' | 'python';

export type ChunkStrategy = 
  | 'fixed'
  | 'alternating'
  | 'boundary_targeted'
  | 'escape_targeted'
  | 'deterministic_random';

export interface RuntimePair {
  primary: RuntimeIdentifier;
  secondary: RuntimeIdentifier;
}

export interface FragmentationProfile {
  strategy: ChunkStrategy;
  params?: Record<string, any>; // e.g., seed for random, sizes for fixed
}

export interface EntropyProfile {
  /** Enables randomized chunk arrival latency within the subprocess bridge. */
  async_chunk_jitter?: boolean;
  /** Enables random splitting of payload boundaries (including inside multi-byte sequences if strategy allows). */
  randomized_boundaries?: boolean;
  /** Simulates partial stdout flushes. */
  stdout_fragmentation?: boolean;

  /** Transport Perturbations */
  partial_stdout_truncation?: boolean;
  delayed_final_newline?: boolean;
  duplicated_chunk_delivery?: boolean;

  /** Scheduler Adversarialism & Starvation */
  scheduler_contention?: boolean;

  /** Sabotage Scaling Intensity (0.0 to 2.0) */
  intensity_factor?: number;

  /** Dedicated Asymmetric Sabotage Intensities */
  jitter_intensity?: number;
  backpressure_intensity?: number;
  stderr_flood_intensity?: number;
  starvation_intensity?: number;
  descriptor_exhaustion?: boolean;
}

export type EcosystemProfile = 'rfc8259_strict' | 'canonical_order_strict' | 'ecma262' | 'legacy_first_win' | 'duplicate_error';

export interface ReplayExecutionContract {
  corpus_id: string;
  deterministic_seed: string;
  runtime_pair: RuntimePair;
  chunk_strategy: ChunkStrategy;
  fragmentation_profile: FragmentationProfile;
  expected_behavior?: 'accept' | 'reject';
  snapshot_schema_version: string;
  entropy_profile?: EntropyProfile;
  topology_flush_interval?: number;
  ecosystem_profile?: EcosystemProfile;
}

/**
 * Generates the canonical deterministic identity for a replay execution.
 */
export function generateReplayId(contract: ReplayExecutionContract): string {
  // Deterministic layout representation for hashing
  const chunkLayoutStr = JSON.stringify({
    strategy: contract.chunk_strategy,
    profile: contract.fragmentation_profile,
  });

  const runtimePairStr = `${contract.runtime_pair.primary}_${contract.runtime_pair.secondary}`;

  const hashData = [
    contract.corpus_id,
    chunkLayoutStr,
    contract.deterministic_seed,
    runtimePairStr,
    contract.snapshot_schema_version
  ].join('|');

  return crypto.createHash('sha256').update(hashData).digest('hex');
}

import fs from 'node:fs';
import path from 'node:path';
