        return { status: 'success', profile };
      },
      err => {
        completedCount++;
        crashesCount++;
        const currentPhase = scheduler.classifyCollapsePhase(timeoutsCount, crashesCount);
        console.log(`[Task ${completedCount}/${tasksCount}] Errored. Phase: ${currentPhase}`);

