          index: i,
          entropyProfile,
          flushInterval,
          status: 'error',
          phase: currentPhase,
          error: err.message
        });

        return { status: 'error', error: err };
      }
    );

    promises.push(taskPromise);
  }

  console.log(`[+] Running tasks concurrently...`);
  await Promise.all(promises);

