  { token_type: 'RIGHT_BRACE', value: '}', start: 16, end: 17 }
];
const ecmaAST = SemanticObjectProjector.buildAST(ecma262Tokens, 'ecma262');
const ecmaObj = ecmaAST.children as any[];
