async function runCampaign(campaignId: number, entry: any): Promise<any[]> {
  const results = [];
  for (let i = 0; i < ITERATIONS_PER_CAMPAIGN; i++) {
    const contract: ReplayExecutionContract = {
      corpus_id: `${entry.corpus_id}_c${campaignId}_i${i}`,
