function findCorrelationIdForPartition(targetPartition: number, prefix: string): string {
  let index = 0;
  const count = 4;
  while (true) {
    const key = `${prefix}-${index}`;
    const hash = crypto.createHash('sha256').update(key).digest();
    if (hash[0] % count === targetPartition) {
      return key;
    }
    index++;
  }
}

